<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import Icon from './Icon.vue'
defineProps<{title:string;wide?:boolean;busy?:boolean}>()
const emit=defineEmits<{close:[]}>(),dialog=ref<HTMLDialogElement|null>(null)
let previousFocus:HTMLElement|null=null,previousOverflow=''
onMounted(()=>{previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.value?.showModal()})
onBeforeUnmount(()=>{dialog.value?.close();document.body.style.overflow=previousOverflow;previousFocus?.focus({preventScroll:true})})
</script>
<template><Teleport to="body"><dialog ref="dialog" class="management-dialog" :class="{'is-wide':wide}" :aria-label="title" @cancel.prevent="!busy&&emit('close')"><header><h2>{{title}}</h2><button type="button" :disabled="busy" aria-label="关闭管理弹窗" @click="emit('close')"><Icon name="X" :size="20"/></button></header><div class="management-content"><slot/></div></dialog></Teleport></template>
<style>
.management-dialog{width:min(580px,calc(100vw - 32px));max-height:88svh;border:1px solid #dce4d5;border-radius:12px;padding:0;background:#fff;color:#364c39;box-shadow:0 20px 80px #1c38262a;overscroll-behavior:contain;font-size:14px}.management-dialog.is-wide{width:min(880px,calc(100vw - 32px))}.management-dialog::backdrop{background:#1d34284f;backdrop-filter:blur(3px)}.management-dialog>header{position:sticky;top:0;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 26px;background:#fff;border-bottom:1px solid #e5eadf}.management-dialog>header h2{font:500 22px/1.5 var(--serif);margin:0}.management-dialog>header button{display:grid;place-items:center;min-width:36px;min-height:36px;border-radius:6px}.management-content{padding:24px 26px}.management-dialog .panel{padding:0;border:0;box-shadow:none}.management-dialog :is(input,select,textarea){font-size:14px;max-width:100%}.management-dialog label{font-size:14px}.management-dialog :is(.quiet-note,.error-message){font-size:13px;line-height:1.85}.management-dialog .button{font-size:13px;letter-spacing:0;min-height:40px}.management-dialog button:focus-visible{outline:2px solid #83a172;outline-offset:3px}.management-dialog .collection-contents li{gap:12px;padding:14px 0;flex-wrap:wrap}.management-dialog .collection-contents li>strong{font-size:16px}.management-dialog .collection-order{font-size:12px}.management-dialog .section-heading h2{font-size:17px}.management-dialog .pen-names-panel>h2{display:none}@media(max-width:540px){.management-content{padding:20px}.management-dialog>header{padding:16px 20px}.management-dialog>header h2{font-size:20px}.management-dialog .collection-order{width:100%;justify-content:flex-end}.management-dialog .collection-add select{min-width:0}}
</style>
